/*
 * SplitSnap type checker. Runs inside headless Microsoft Edge, opened by tools/typecheck.html,
 * which tools/typecheck.ps1 drives.
 *
 * Input, from tools/.out/typecheck-input.js (generated by typecheck.ps1):
 *   window.__TYPECHECK_INPUT__ = {
 *     files: { 'app/App.tsx': '<source>', ... },     // every .ts/.tsx under app/
 *     compilerOptions: { strict: true, ... },          // tsconfig-style JSON
 *     pins: { 'react-native': '~0.83.0', ... },        // versions for top-level packages
 *     typesFor: { react: '@types/react' },             // packages whose types live elsewhere
 *     allowedPackages: [...],                          // ARCHITECTURE.md import allow-list
 *     shimAll: false                                   // true = skip type acquisition
 *   }
 *
 * Type acquisition: every import is resolved with TypeScript's own module resolution against
 * an in-memory file system. Packages are listed with the jsDelivr data API
 * (https://data.jsdelivr.com/v1/packages/npm/<pkg>@<version>?structure=flat) so the resolver
 * knows which files exist, and only the files it actually resolves (.d.ts, package.json)
 * are downloaded from https://cdn.jsdelivr.net/npm/<pkg>@<version>/<path>. Dependencies are
 * followed recursively, using each package's dependency ranges. Packages that cannot be
 * acquired fall back to an ambient `declare module 'x';` shim, which is reported.
 *
 * Output: ASCII-only JSON in <pre id="typecheck-results">.
 */
(function () {
  'use strict';

  var RESULT_ID = 'typecheck-results';
  var PROGRESS_ID = 'typecheck-progress';
  var CDN = 'https://cdn.jsdelivr.net/npm/';
  var DATA_API = 'https://data.jsdelivr.com/v1/packages/npm/';
  var TS_LIB_DIR = '/node_modules/typescript/lib';
  var SHIM_FILE = '/__shims__/ambient-modules.d.ts';
  // Probe that makes the compiler compute the Ionicons glyph-name union from the real typings.
  var GLYPH_FILE = '/__splitsnap__/ionicons-glyphs.ts';
  var GLYPH_SOURCE = "import type { Ionicons } from '@expo/vector-icons';\n" +
    "import type { ComponentProps } from 'react';\n" +
    "export type IoniconsGlyph = NonNullable<ComponentProps<typeof Ionicons>['name']>;\n";
  var MAX_PARALLEL = 12;
  var MAX_ROUNDS = 60;
  var VALID_PACKAGE_NAME = /^(@[a-z0-9][\w.~-]*\/)?[a-z0-9][\w.~-]*$/i;

  var input = window.__TYPECHECK_INPUT__;
  var started = Date.now();

  // ---------------------------------------------------------------------------------------
  // Output

  function asciiJson(value) {
    return JSON.stringify(value).replace(/[^ -~]|[<>&]/g, function (c) {
      return '\\u' + ('0000' + c.charCodeAt(0).toString(16)).slice(-4);
    });
  }

  function writeResult(result) {
    var el = document.getElementById(RESULT_ID);
    el.textContent = asciiJson(result);
    el.setAttribute('data-done', '1');
    var summary = document.getElementById('summary');
    if (summary) {
      summary.textContent = result.fatal ? 'FATAL: ' + result.fatal :
        (result.diagnostics || []).map(function (d) {
          return (d.file ? d.file + '(' + d.line + ',' + d.col + '): ' : '') + d.category + ' TS' + d.code + ': ' + d.message;
        }).join('\n') || 'No errors.';
    }
  }

  function setProgress(text) {
    var el = document.getElementById(PROGRESS_ID);
    if (el) el.textContent = text;
    console.log('[typecheck] ' + ((Date.now() - started) / 1000).toFixed(1) + 's ' + text);
  }

  // ---------------------------------------------------------------------------------------
  // Paths

  function normalize(path) {
    var out = [];
    path.split('/').forEach(function (part) {
      if (part === '' || part === '.') return;
      if (part === '..') out.pop();
      else out.push(part);
    });
    return '/' + out.join('/');
  }

  function dirname(path) {
    var i = path.lastIndexOf('/');
    return i <= 0 ? '/' : path.slice(0, i);
  }

  function isRelative(spec) { return /^\.{1,2}(\/|$)/.test(spec) || spec.charAt(0) === '/'; }

  function packageNameOf(spec) {
    var parts = spec.split('/');
    return spec.charAt(0) === '@' ? parts.slice(0, 2).join('/') : parts[0];
  }

  function typesPackageName(name) {
    return '@types/' + (name.charAt(0) === '@' ? name.slice(1).replace('/', '__') : name);
  }

  // '/node_modules/@scope/pkg/lib/x.d.ts' -> { name: '@scope/pkg', rel: '/lib/x.d.ts' }
  function packageOfPath(path) {
    var m = /^\/node_modules\/((?:@[^/]+\/)?[^/@][^/]*)(\/.*)?$/.exec(path);
    return m ? { name: m[1], rel: m[2] || '' } : null;
  }

  // ---------------------------------------------------------------------------------------
  // Network (bounded parallelism, retries)

  var stats = { requests: 0, bytes: 0, failures: 0 };
  var active = 0;
  var waiting = [];

  function limited(task) {
    return new Promise(function (resolve, reject) {
      function run() {
        active++;
        task().then(resolve, reject).then(function () {
          active--;
          if (waiting.length) waiting.shift()();
        });
      }
      if (active < MAX_PARALLEL) run(); else waiting.push(run);
    });
  }

  function sleep(ms) { return new Promise(function (r) { setTimeout(r, ms); }); }

  // Response cache, persisted by typecheck.ps1 in tools/.cache/typecheck-cache.js:
  // URL -> text (null = 404). Versioned package files, listings and resolved pins do not
  // change, so a warm run needs no network at all. typecheck.ps1 -Refresh starts over.
  var cacheIn = (window.__TYPECHECK_CACHE__ && window.__TYPECHECK_CACHE__.responses) || {};
  var cacheOut = Object.assign({}, cacheIn);
  var cacheStats = { hits: 0, added: 0 };

  function cachedFetchText(url, transform) {
    if (Object.prototype.hasOwnProperty.call(cacheIn, url)) {
      cacheStats.hits++;
      return Promise.resolve(cacheIn[url]);
    }
    return fetchText(url).then(function (text) {
      if (text !== null && transform) text = transform(text);
      cacheOut[url] = text;
      cacheStats.added++;
      return text;
    });
  }

  // Keep only file names from a jsDelivr listing (hashes and sizes are not needed).
  function trimListing(text) {
    var files = (JSON.parse(text).files || []).map(function (f) { return { name: f.name }; });
    return JSON.stringify({ files: files });
  }

  // Resolves to the response text, or null on 404.
  function fetchText(url) {
    return limited(async function () {
      for (var attempt = 1; ; attempt++) {
        try {
          if (input.debug) console.log('[typecheck] GET ' + url + (attempt > 1 ? ' (attempt ' + attempt + ')' : ''));
          var res = await fetch(url);
          if (input.debug) console.log('[typecheck] ' + res.status + ' ' + url);
          if (res.status === 404) return null;
          if (!res.ok) throw new Error('HTTP ' + res.status);
          var text = await res.text();
          stats.requests++;
          stats.bytes += text.length;
          return text;
        } catch (e) {
          if (input.debug) console.log('[typecheck] FAILED ' + url + ': ' + (e && e.message ? e.message : e));
          if (attempt >= 3) {
            stats.failures++;
            throw new Error('GET ' + url + ' failed: ' + (e && e.message ? e.message : e));
          }
          await sleep(300 * attempt);
        }
      }
    });
  }

  // ---------------------------------------------------------------------------------------
  // In-memory file system and packages

  var vfs = new Map();          // absolute path -> text
  var appDirs = new Set(['/']);
  var packages = new Map();     // name -> { name, version, files: Set, dirs: Set, pkgJson, state, error, fetched }
  var requestedFiles = new Set();

  function addAppFile(path, text) {
    vfs.set(path, text);
    for (var d = dirname(path); d !== '/'; d = dirname(d)) appDirs.add(d);
  }

  function cleanRange(range) {
    if (!range || /^(npm:|workspace:|file:|link:|git|https?:|github:)/.test(range)) return 'latest';
    return range;
  }

  function declaredRange(pkgJson, name) {
    var groups = ['dependencies', 'peerDependencies', 'optionalDependencies', 'devDependencies'];
    for (var i = 0; i < groups.length; i++) {
      if (pkgJson[groups[i]] && pkgJson[groups[i]][name]) return pkgJson[groups[i]][name];
    }
    return null;
  }

  // Pin, else the importing package's own range, else the range any other loaded package
  // declares (e.g. react-native pins @react-native/assets-registry that expo-asset imports).
  function rangeFor(name, fromFile) {
    if (input.pins && input.pins[name]) return input.pins[name];
    var owner = packageOfPath(fromFile);
    var rec = owner && packages.get(owner.name);
    var range = rec && rec.pkgJson ? declaredRange(rec.pkgJson, name) : null;
    if (!range) {
      packages.forEach(function (other) {
        if (!range && other.pkgJson) range = declaredRange(other.pkgJson, name);
      });
    }
    return range ? cleanRange(range) : 'latest';
  }

  async function resolveVersion(name, range) {
    if (/^\d+\.\d+\.\d+(-[0-9A-Za-z.-]+)?$/.test(range)) return range;
    var text = await cachedFetchText(DATA_API + name + '/resolved?specifier=' + encodeURIComponent(range));
    var version = text ? JSON.parse(text).version : null;
    if (!version) {
      var e = new Error('no published version of ' + name + ' matches "' + range + '"');
      e.notFound = true;
      throw e;
    }
    return version;
  }

  function loadPackage(name, range, requestedBy) {
    if (packages.has(name)) return packages.get(name).promise;
    var rec = { name: name, range: range, requestedBy: requestedBy, version: null, files: null, dirs: null, pkgJson: null, hasTypes: false, state: 'loading', error: null, fetched: 0 };
    packages.set(name, rec);
    rec.promise = (async function () {
      try {
        rec.version = await resolveVersion(name, range);
        var listing = await cachedFetchText(DATA_API + name + '@' + rec.version + '?structure=flat', trimListing);
        if (!listing) {
          var missing = new Error(name + '@' + rec.version + ' does not exist on npm');
          missing.notFound = true;
          throw missing;
        }
        var files = JSON.parse(listing).files || [];
        rec.files = new Set();
        rec.dirs = new Set();
        files.forEach(function (f) {
          rec.files.add(f.name);
          if (/\.d\.[cm]?ts$/.test(f.name)) rec.hasTypes = true;
          for (var d = dirname(f.name); d !== '/'; d = dirname(d)) rec.dirs.add(d);
        });
        var pj = await cachedFetchText(CDN + name + '@' + rec.version + '/package.json');
        if (!pj) throw new Error('package.json not found');
        rec.pkgJson = JSON.parse(pj);
        vfs.set('/node_modules/' + name + '/package.json', pj);
        rec.state = 'ready';
      } catch (e) {
        rec.state = 'failed';
        rec.notFound = !!(e && e.notFound);
        rec.error = e && e.message ? e.message : String(e);
      }
    })();
    return rec.promise;
  }

  function urlForPath(path) {
    if (path.indexOf(TS_LIB_DIR + '/') === 0) return CDN + 'typescript@' + ts.version + '/lib/' + path.slice(TS_LIB_DIR.length + 1);
    var info = packageOfPath(path);
    var rec = info && packages.get(info.name);
    if (!rec || rec.state !== 'ready') return null;
    return CDN + info.name + '@' + rec.version + info.rel;
  }

  async function fetchFile(path) {
    var url = urlForPath(path);
    if (!url) return false;
    var text = await cachedFetchText(url);
    if (text === null) return false;
    vfs.set(path, text);
    var info = packageOfPath(path);
    if (info && packages.has(info.name)) packages.get(info.name).fetched++;
    return true;
  }

  // Module-resolution host: knows every file of every listed package, fetched or not, so
  // resolution can pick the right file; the crawler then downloads exactly that file.
  var host = {
    fileExists: function (path) {
      if (vfs.has(path)) return true;
      var info = packageOfPath(path);
      if (!info) return false;
      var rec = packages.get(info.name);
      return !!rec && rec.state === 'ready' && rec.files.has(info.rel);
    },
    readFile: function (path) { return vfs.get(path); },
    directoryExists: function (dir) {
      dir = dir.replace(/\/+$/, '') || '/';
      if (dir === '/node_modules' || dir === '/node_modules/@types' || appDirs.has(dir)) return true;
      if (dir === TS_LIB_DIR || dir === '/node_modules/typescript' || dir === '/__shims__') return true;
      if (/^\/node_modules\/@[^/]+$/.test(dir)) return true;
      var info = packageOfPath(dir);
      if (!info) return false;
      var rec = packages.get(info.name);
      if (!rec || rec.state !== 'ready') return false;
      return info.rel === '' || rec.dirs.has(info.rel);
    },
    getDirectories: function () { return []; },
    realpath: function (p) { return p; },
    getCurrentDirectory: function () { return '/'; },
    useCaseSensitiveFileNames: function () { return true; }
  };

  // ---------------------------------------------------------------------------------------
  // Crawler: resolve imports, load packages / files they need, repeat until stable

  var options;
  var appFiles = [];
  var shimmed = new Map();          // package name -> reason
  var unresolvedInLibraries = [];   // bare imports inside .d.ts files that could not be typed
  var contractViolations = [];

  function isTypedExtension(ext) {
    return ['.d.ts', '.d.mts', '.d.cts', '.ts', '.tsx', '.mts', '.cts', '.json'].indexOf(ext) !== -1;
  }

  function allowedInShimMode(name) {
    return name === '@types/react' || name === 'csstype';
  }

  // Returns true when `file` must be scanned again after the requested packages arrive.
  function scanFile(file, need) {
    var info = ts.preProcessFile(vfs.get(file), true, true);
    var mustRetry = false;
    var specs = info.importedFiles.map(function (r) { return r.fileName; });
    if (/\.tsx$/.test(file) && !/^\/node_modules\//.test(file)) specs.push('react/jsx-runtime');
    specs.forEach(function (spec) {
      if (needModule(spec, file, need)) mustRetry = true;
    });
    info.typeReferenceDirectives.forEach(function (ref) {
      var r = ts.resolveTypeReferenceDirective(ref.fileName, file, options, host).resolvedTypeReferenceDirective;
      if (r && r.resolvedFileName) {
        if (!vfs.has(r.resolvedFileName)) need.files.add(r.resolvedFileName);
      } else if (!input.shimAll) {
        var typesName = ref.fileName.indexOf('@types/') === 0 ? ref.fileName : typesPackageName(ref.fileName);
        if (!packages.has(typesName)) { need.packages.set(typesName, rangeFor(typesName, file)); mustRetry = true; }
      }
    });
    info.referencedFiles.forEach(function (ref) {
      var p = normalize(dirname(file) + '/' + ref.fileName);
      if (!vfs.has(p) && host.fileExists(p)) need.files.add(p);
    });
    info.libReferenceDirectives.forEach(function (ref) { needLib(ref.fileName.toLowerCase(), need); });
    return mustRetry;
  }

  function needLib(name, need) {
    var path = TS_LIB_DIR + '/lib.' + name + '.d.ts';
    if (!vfs.has(path)) need.files.add(path);
  }

  function needModule(spec, file, need) {
    var resolved = ts.resolveModuleName(spec, file, options, host).resolvedModule;
    if (resolved && isTypedExtension(resolved.extension)) {
      if (!vfs.has(resolved.resolvedFileName)) need.files.add(resolved.resolvedFileName);
      return false;
    }
    if (isRelative(spec)) return false;   // a broken relative import: the compiler reports it
    var name = packageNameOf(spec);
    if (!VALID_PACKAGE_NAME.test(name)) return false;   // e.g. an '@/...' alias: the compiler reports it
    var fromApp = !/^\/node_modules\//.test(file);
    if (input.shimAll && !allowedInShimMode(input.typesFor[name] || name)) {
      if (fromApp) shimmed.set(name, 'shim mode (-ShimAll)');
      return false;
    }
    var candidates = input.typesFor[name] ? [input.typesFor[name]] : [name, typesPackageName(name)];
    for (var i = 0; i < candidates.length; i++) {
      var rec = packages.get(candidates[i]);
      if (!rec) {
        need.packages.set(candidates[i], rangeFor(candidates[i], file));
        return true;
      }
      // A package that ships its own typings: an unresolvable subpath is not fixed by @types.
      if (rec.state === 'ready' && rec.hasTypes) {
        candidates = candidates.slice(0, i + 1);
        break;
      }
    }
    var reasons = candidates.map(function (c) {
      var r = packages.get(c);
      return c + (r.state === 'failed' ? ' (' + r.error + ')' : r.version ? '@' + r.version + ' (no matching type definitions)' : '');
    }).join('; ');
    // A package that does not exist at all is a real error (typo?), so it is not shimmed.
    var nothingPublished = candidates.every(function (c) { return packages.get(c).notFound; });
    if (fromApp && !nothingPublished) shimmed.set(name, reasons);
    else if (unresolvedInLibraries.length < 200) unresolvedInLibraries.push(spec + ' from ' + file.replace(/^\//, ''));
    return false;
  }

  async function acquireTypes() {
    var queue = appFiles.slice();
    if (vfs.has(GLYPH_FILE)) queue.push(GLYPH_FILE);
    var scanned = new Set();
    var need = { packages: new Map(), files: new Set() };
    (input.compilerOptions.lib || []).forEach(function (lib) { needLib(String(lib).toLowerCase(), need); });
    for (var round = 1; round <= MAX_ROUNDS; round++) {
      var retry = [];
      queue.forEach(function (file) {
        if (!vfs.has(file) || scanned.has(file)) return;
        if (scanFile(file, need)) retry.push(file); else scanned.add(file);
      });
      if (!need.packages.size && !need.files.size) return;
      setProgress('round ' + round + ': ' + need.packages.size + ' package(s), ' + need.files.size + ' file(s)');
      var pkgJobs = [];
      need.packages.forEach(function (range, name) { pkgJobs.push(loadPackage(name, range, '')); });
      await Promise.all(pkgJobs);
      var fileList = Array.from(need.files).filter(function (f) { return !vfs.has(f) && !requestedFiles.has(f); });
      fileList.forEach(function (f) { requestedFiles.add(f); });
      var fetched = await Promise.all(fileList.map(function (f) {
        return fetchFile(f).catch(function () { return false; });
      }));
      queue = retry.concat(fileList.filter(function (f, i) { return fetched[i]; }));
      need = { packages: new Map(), files: new Set() };
    }
  }

  // ---------------------------------------------------------------------------------------
  // Contract check: only the packages allowed by ARCHITECTURE.md may be imported from app/

  function lineCol(text, pos) {
    var line = 1;
    var last = -1;
    for (var i = 0; i < pos; i++) {
      if (text.charCodeAt(i) === 10) { line++; last = i; }
    }
    return { line: line, col: pos - last };
  }

  function checkAllowedImports() {
    var allowed = input.allowedPackages || [];
    if (!allowed.length) return;
    appFiles.forEach(function (file) {
      var text = vfs.get(file);
      ts.preProcessFile(text, true, true).importedFiles.forEach(function (ref) {
        var spec = ref.fileName;
        if (isRelative(spec)) return;
        var name = packageNameOf(spec);
        if (allowed.indexOf(name) !== -1) return;
        var pos = lineCol(text, ref.pos);
        contractViolations.push({
          file: file.slice(1), line: pos.line, col: pos.col, code: 'SPLITSNAP1', category: 'error',
          message: "Import of '" + spec + "' is not allowed: only the packages listed in docs/ARCHITECTURE.md section 1 rule 3 may be used" +
            (spec.indexOf('@/') === 0 ? ' (and path aliases are not allowed; use relative imports)' : '') + '.'
        });
      });
    });
  }

  // ---------------------------------------------------------------------------------------
  // Snack compatibility (SPLITSNAP3): Snack's in-browser Babel (@react-native/babel-preset 0.75
  // with the Flow syntax plugin) fails with "Unexpected token" on numeric literal types such as
  // `type Level = 1 | 2 | 3` or `sign: 1 | -1`. Use `(typeof LEVELS)[number]` over an
  // `as const` array, or plain `number`, instead.

  function checkSnackSyntax() {
    appFiles.forEach(function (file) {
      var text = vfs.get(file);
      var sf = ts.createSourceFile(file, text, ts.ScriptTarget.ES2022, true,
        /\.tsx$/.test(file) ? ts.ScriptKind.TSX : ts.ScriptKind.TS);
      (function visit(node) {
        if (node.kind === ts.SyntaxKind.LiteralType) {
          var lit = node.literal;
          var numeric = lit.kind === ts.SyntaxKind.NumericLiteral || lit.kind === ts.SyntaxKind.BigIntLiteral ||
            (lit.kind === ts.SyntaxKind.PrefixUnaryExpression && lit.operand.kind === ts.SyntaxKind.NumericLiteral);
          if (numeric) {
            var pos = lineCol(text, node.getStart(sf));
            contractViolations.push({
              file: file.slice(1), line: pos.line, col: pos.col, code: 'SPLITSNAP3', category: 'error',
              message: "Numeric literal type '" + node.getText(sf) + "' breaks Expo Snack's Babel parser. " +
                'Use (typeof VALUES)[number] over an `as const` array, or number.'
            });
          }
        }
        ts.forEachChild(node, visit);
      })(sf);
    });
  }

  // ---------------------------------------------------------------------------------------
  // Dark mode (SPLITSNAP4): `colors` from theme.ts follows the active theme only when it is read
  // while rendering. A read at module level (outside every function, e.g. a constant style object)
  // freezes the colour of the theme that was active when the file loaded.

  function checkThemeReads() {
    appFiles.forEach(function (file) {
      if (/\/src\/theme\.ts$/.test(file)) return;
      var text = vfs.get(file);
      var sf = ts.createSourceFile(file, text, ts.ScriptTarget.ES2022, true,
        /\.tsx$/.test(file) ? ts.ScriptKind.TSX : ts.ScriptKind.TS);
      var importsColors = sf.statements.some(function (st) {
        if (!ts.isImportDeclaration(st) || !/(^|\/)theme$/.test(st.moduleSpecifier.text)) return false;
        var nb = st.importClause && st.importClause.namedBindings;
        return !!(nb && ts.isNamedImports(nb) && nb.elements.some(function (e) { return e.name.text === 'colors'; }));
      });
      if (!importsColors) return;
      (function visit(node, inFunction) {
        if (ts.isFunctionLike(node)) inFunction = true;
        if (!inFunction && ts.isPropertyAccessExpression(node) && ts.isIdentifier(node.expression) && node.expression.text === 'colors') {
          var pos = lineCol(text, node.getStart(sf));
          contractViolations.push({
            file: file.slice(1), line: pos.line, col: pos.col, code: 'SPLITSNAP4', category: 'error',
            message: "'" + node.getText(sf) + "' is read when the file loads, so it will not follow dark mode. " +
              'Read it while rendering, or build styles with themed((colors) => StyleSheet.create({...})).'
          });
        }
        ts.forEachChild(node, function (child) { visit(child, inFunction); });
      })(sf, false);
    });
  }

  // ---------------------------------------------------------------------------------------
  // Icon names (SPLITSNAP2). TypeScript checks glyph names only where a prop is typed with the
  // Ionicons name union; the app's own components take `icon: string`, so string literals that
  // flow into icon positions are checked against the glyph map of the real typings:
  //   - JSX `name` on <Ionicons>/<...Icon>, and any attribute, property, parameter default or
  //     call argument (matched by parameter name) called icon / iconName / glyph / ...Icon;
  //   - every glyph-shaped string inside a variable named ...icon(s) (e.g. TAB_ICONS).
  // Conditionals, ?? / || / && and `as` are looked through; other expressions count when their
  // type is a small union of string literals.

  var ICON_KEY = /^(icon|iconName|glyph)$|[a-z0-9](Icon|IconName)$/;
  var ICON_TAG = /(^|\.)(Ionicons|[A-Za-z]*Icon)$/;
  var ICON_COLLECTION = /icons?$/i;
  var GLYPH_SHAPE = /^[a-z0-9]+(-[a-z0-9]+)*$/;

  function ioniconsGlyphs(program) {
    var sf = program.getSourceFile(GLYPH_FILE);
    if (!sf) return null;
    var checker = program.getTypeChecker();
    var decl = sf.statements.filter(ts.isTypeAliasDeclaration)[0];
    var symbol = decl && checker.getSymbolAtLocation(decl.name);
    if (!symbol) return null;
    var type = checker.getDeclaredTypeOfSymbol(symbol);
    var names = new Set();
    (type.isUnion() ? type.types : [type]).forEach(function (t) {
      if (t.isStringLiteral()) names.add(t.value);
    });
    return names.size >= 100 ? names : null;   // fewer means the typings were not real
  }

  function editDistance(a, b, limit) {
    if (Math.abs(a.length - b.length) > limit) return limit + 1;
    var prev = [];
    for (var j = 0; j <= b.length; j++) prev.push(j);
    for (var i = 1; i <= a.length; i++) {
      var cur = [i];
      var best = i;
      for (j = 1; j <= b.length; j++) {
        cur.push(Math.min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + (a.charAt(i - 1) === b.charAt(j - 1) ? 0 : 1)));
        if (cur[j] < best) best = cur[j];
      }
      if (best > limit) return limit + 1;
      prev = cur;
    }
    return prev[b.length];
  }

  function suggestGlyph(value, glyphs) {
    var best = null;
    var bestScore = 4;
    glyphs.forEach(function (g) {
      // A different first letter is rarely a typo of the same word ('chek' is not 'key').
      var d = editDistance(value, g, 3) + (g.charAt(0) === value.charAt(0) ? 0 : 1);
      if (d < bestScore || (d === bestScore && best && g.length < best.length)) { best = g; bestScore = d; }
    });
    if (!best && glyphs.has(value + '-outline')) best = value + '-outline';
    return best;
  }

  function checkIconNames(program, glyphs, version) {
    var checker = program.getTypeChecker();
    var found = [];
    var seen = new Set();
    var checked = 0;

    function propName(name) {
      return name && (ts.isIdentifier(name) || ts.isStringLiteral(name)) ? name.text : null;
    }

    function verify(sf, node, value, reported) {
      var key = sf.fileName + ':' + node.pos + ':' + value;
      if (seen.has(key)) return;
      seen.add(key);
      // Already type-checked when the literal sits where the glyph union is expected.
      if (ts.isStringLiteralLike(node)) {
        var ctx = checker.getContextualType(node);
        if (ctx && ctx.isUnion() && ctx.types.length >= 100) return;
      }
      checked++;
      if (glyphs.has(value)) return;
      if (reported.has(value) && !ts.isStringLiteralLike(node)) return;
      reported.add(value);
      var pos = sf.getLineAndCharacterOfPosition(node.getStart(sf));
      var hint = suggestGlyph(value, glyphs);
      found.push({
        file: sf.fileName.slice(1), line: pos.line + 1, col: pos.character + 1, code: 'SPLITSNAP2', category: 'error',
        message: "'" + value + "' is not an Ionicons glyph name (@expo/vector-icons " + version + ')' +
          (hint ? "; did you mean '" + hint + "'?" : '.') + ' Unknown names render as a placeholder or nothing.'
      });
    }

    // Literals that an icon-position expression can evaluate to.
    function direct(sf, expr, reported) {
      if (!expr) return;
      if (ts.isStringLiteralLike(expr)) { verify(sf, expr, expr.text, reported); return; }
      if (ts.isJsxExpression(expr) || ts.isParenthesizedExpression(expr) || ts.isAsExpression(expr) ||
          ts.isNonNullExpression(expr) || ts.isTypeAssertionExpression(expr) ||
          (ts.isSatisfiesExpression && ts.isSatisfiesExpression(expr))) {
        direct(sf, expr.expression, reported);
        return;
      }
      if (ts.isConditionalExpression(expr)) { direct(sf, expr.whenTrue, reported); direct(sf, expr.whenFalse, reported); return; }
      if (ts.isBinaryExpression(expr)) {
        var op = expr.operatorToken.kind;
        if (op === ts.SyntaxKind.BarBarToken || op === ts.SyntaxKind.QuestionQuestionToken) direct(sf, expr.left, reported);
        if (op === ts.SyntaxKind.BarBarToken || op === ts.SyntaxKind.QuestionQuestionToken || op === ts.SyntaxKind.AmpersandAmpersandToken) direct(sf, expr.right, reported);
        return;
      }
      if (!ts.isIdentifier(expr) && !ts.isPropertyAccessExpression(expr) && !ts.isElementAccessExpression(expr) && !ts.isCallExpression(expr)) return;
      var type = checker.getTypeAtLocation(expr);
      var parts = type.isUnion() ? type.types : [type];
      if (parts.length > 50) return;
      var literals = [];
      for (var i = 0; i < parts.length; i++) {
        if (parts[i].isStringLiteral()) literals.push(parts[i].value);
        else if (!(parts[i].flags & (ts.TypeFlags.Undefined | ts.TypeFlags.Null))) return;
      }
      literals.forEach(function (v) { verify(sf, expr, v, reported); });
    }

    // Every glyph-shaped string in a collection such as TAB_ICONS. In an object that has an
    // icon-like key, only that key holds icons (the rest are labels, colours, ...).
    function deep(sf, node, reported) {
      if (!node) return;
      if (ts.isStringLiteralLike(node)) {
        if (GLYPH_SHAPE.test(node.text)) verify(sf, node, node.text, reported);
        return;
      }
      if (ts.isParenthesizedExpression(node) || ts.isAsExpression(node) || ts.isTypeAssertionExpression(node) ||
          (ts.isSatisfiesExpression && ts.isSatisfiesExpression(node))) {
        deep(sf, node.expression, reported);
        return;
      }
      if (ts.isConditionalExpression(node)) { deep(sf, node.whenTrue, reported); deep(sf, node.whenFalse, reported); return; }
      if (ts.isArrayLiteralExpression(node)) { node.elements.forEach(function (e) { deep(sf, e, reported); }); return; }
      if (ts.isObjectLiteralExpression(node)) {
        var hasIconKey = node.properties.some(function (p) { return ts.isPropertyAssignment(p) && ICON_KEY.test(propName(p.name) || ''); });
        node.properties.forEach(function (p) {
          if (!ts.isPropertyAssignment(p)) return;
          var init = p.initializer;
          if (ts.isObjectLiteralExpression(init) || ts.isArrayLiteralExpression(init)) deep(sf, init, reported);
          else if (!hasIconKey) deep(sf, init, reported);
        });
      }
    }

    appFiles.forEach(function (file) {
      var sf = program.getSourceFile(file);
      if (!sf) return;
      var reported = new Set();
      (function visit(node) {
        if (ts.isJsxAttribute(node) && ts.isIdentifier(node.name)) {
          var attr = node.name.text;
          var tag = node.parent.parent.tagName.getText(sf);
          if ((attr === 'name' && ICON_TAG.test(tag)) || ICON_KEY.test(attr)) direct(sf, node.initializer, reported);
        } else if (ts.isPropertyAssignment(node) && ICON_KEY.test(propName(node.name) || '')) {
          direct(sf, node.initializer, reported);
        } else if ((ts.isParameter(node) || ts.isBindingElement(node)) && node.initializer &&
            ts.isIdentifier(node.name) && ICON_KEY.test(node.name.text)) {
          direct(sf, node.initializer, reported);
        } else if (ts.isVariableDeclaration(node) && node.initializer && ts.isIdentifier(node.name)) {
          if (ICON_KEY.test(node.name.text)) direct(sf, node.initializer, reported);
          else if (ICON_COLLECTION.test(node.name.text)) deep(sf, node.initializer, reported);
        } else if (ts.isCallExpression(node) && node.arguments.length) {
          var callee = node.expression.getText(sf);
          var signature = null;
          try { signature = checker.getResolvedSignature(node); } catch (e) { signature = null; }
          var params = signature ? signature.getParameters() : [];
          node.arguments.forEach(function (arg, i) {
            var param = params[i];
            if ((param && ICON_KEY.test(param.name)) || (i === 0 && /(^|\.)resolveIconName$/.test(callee))) direct(sf, arg, reported);
          });
        }
        ts.forEachChild(node, visit);
      })(sf);
    });
    return { diagnostics: found, checked: checked };
  }

  // ---------------------------------------------------------------------------------------
  // Compile

  function toDiagnostic(d) {
    var out = {
      code: d.code,
      category: ts.DiagnosticCategory[d.category].toLowerCase(),
      message: ts.flattenDiagnosticMessageText(d.messageText, '\n')
    };
    if (d.file) {
      var pos = d.file.getLineAndCharacterOfPosition(d.start || 0);
      out.file = d.file.fileName.replace(/^\//, '');
      out.line = pos.line + 1;
      out.col = pos.character + 1;
    }
    return out;
  }

  // What app code takes from each module specifier: named imports / re-exports, members used
  // through a namespace import (`Picker.launchCameraAsync`) and whether a default import exists.
  function collectImportUsage() {
    var usage = new Map();
    appFiles.forEach(function (file) {
      var sf = ts.createSourceFile(file, vfs.get(file), ts.ScriptTarget.Latest, true);
      sf.statements.forEach(function (st) {
        var isImport = ts.isImportDeclaration(st);
        if (!isImport && !(ts.isExportDeclaration(st) && st.moduleSpecifier)) return;
        if (!ts.isStringLiteral(st.moduleSpecifier)) return;
        var spec = st.moduleSpecifier.text;
        var u = usage.get(spec) || { names: new Set(), hasDefault: false };
        usage.set(spec, u);
        var named = isImport ? st.importClause && st.importClause.namedBindings : st.exportClause;
        if (isImport && st.importClause && st.importClause.name) u.hasDefault = true;
        if (named && (ts.isNamedImports(named) || ts.isNamedExports(named))) {
          named.elements.forEach(function (e) { u.names.add((e.propertyName || e.name).text); });
        } else if (named && ts.isNamespaceImport(named)) {
          var re = new RegExp('\\b' + named.name.text + '\\.([A-Za-z_$][\\w$]*)', 'g');
          for (var m = re.exec(sf.text); m; m = re.exec(sf.text)) u.names.add(m[1]);
        }
      });
    });
    return usage;
  }

  // Shims for packages without real typings. Every name the app imports is both an `any` value
  // (assignable anywhere, e.g. to useContext or a weak type) and a generic type alias of `any`,
  // so `StyleProp<TextStyle>` and namespace members work. Calls with type arguments on these
  // values (`Platform.select<T>()`) raise TS2347, which check() drops while shims are active.
  function buildShims() {
    var usage = collectImportUsage();
    var text = '// Generated: packages whose type definitions could not be acquired.\n';
    shimmed.forEach(function (reason, name) {
      usage.forEach(function (u, spec) {
        if (packageNameOf(spec) !== name) return;
        text += "declare module '" + spec + "' {\n";
        u.names.forEach(function (n) {
          if (n === 'default') { u.hasDefault = true; return; }
          text += '  export const ' + n + ': any;\n  export type ' + n + '<A = any, B = any, C = any, D = any> = any;\n';
        });
        if (u.hasDefault) text += '  const shimDefault: any;\n  export default shimDefault;\n';
        text += '}\n';
      });
      text += "declare module '" + name + "/*';\n";
    });
    return text;
  }

  // TS2347 "Untyped function calls may not accept type arguments": only untyped (shimmed) values.
  var SHIM_ARTEFACT_CODES = [2347];

  function check() {
    var shimText = '';
    if (shimmed.size) {
      shimText = buildShims();
      vfs.set(SHIM_FILE, shimText);
      // Callbacks passed to untyped components get no contextual type; in shim mode that would
      // flag every `({ pressed }) => ...` as an implicit any.
      if (input.shimAll) options.noImplicitAny = false;
    }
    var compilerHost = {
      fileExists: host.fileExists,
      readFile: host.readFile,
      directoryExists: host.directoryExists,
      getDirectories: host.getDirectories,
      realpath: host.realpath,
      getSourceFile: function (fileName, languageVersionOrOptions) {
        var text = vfs.get(fileName);
        return text === undefined ? undefined :
          ts.createSourceFile(fileName, text, languageVersionOrOptions, !/^\/node_modules\//.test(fileName));
      },
      getDefaultLibFileName: function (o) { return TS_LIB_DIR + '/' + ts.getDefaultLibFileName(o); },
      getDefaultLibLocation: function () { return TS_LIB_DIR; },
      writeFile: function () {},
      getCurrentDirectory: function () { return '/'; },
      getCanonicalFileName: function (f) { return f; },
      useCaseSensitiveFileNames: function () { return true; },
      getNewLine: function () { return '\n'; }
    };
    var roots = appFiles.slice();
    if (shimText) roots.push(SHIM_FILE);
    if (vfs.has(GLYPH_FILE)) roots.push(GLYPH_FILE);
    var program = ts.createProgram({ rootNames: roots, options: options, host: compilerHost });
    var diags = [].concat(program.getOptionsDiagnostics(), program.getGlobalDiagnostics());
    appFiles.forEach(function (file) {
      var sf = program.getSourceFile(file);
      if (!sf) return;
      diags = diags.concat(program.getSyntacticDiagnostics(sf), program.getSemanticDiagnostics(sf));
    });
    if (shimText) diags = diags.filter(function (d) { return SHIM_ARTEFACT_CODES.indexOf(d.code) === -1; });
    var sorted = Array.prototype.map.call(ts.sortAndDeduplicateDiagnostics(diags), toDiagnostic);

    var icons = { state: 'skipped', reason: 'no app file imports @expo/vector-icons' };
    if (input.shimAll) icons.reason = 'shim mode (-ShimAll) has no glyph map';
    else if (vfs.has(GLYPH_FILE)) {
      var glyphs = ioniconsGlyphs(program);
      var iconPkg = packages.get('@expo/vector-icons');
      if (!glyphs) icons.reason = 'the @expo/vector-icons typings did not load';
      else {
        var iconResult = checkIconNames(program, glyphs, iconPkg && iconPkg.version);
        sorted = sorted.concat(iconResult.diagnostics).sort(function (a, b) {
          if ((a.file || '') !== (b.file || '')) return (a.file || '') < (b.file || '') ? -1 : 1;
          return (a.line || 0) - (b.line || 0) || (a.col || 0) - (b.col || 0);
        });
        icons = { state: 'checked', glyphs: glyphs.size, literals: iconResult.checked, version: iconPkg && iconPkg.version };
      }
    }
    return { diagnostics: sorted, sourceFiles: program.getSourceFiles().length, icons: icons };
  }

  // ---------------------------------------------------------------------------------------

  async function main() {
    if (window.__TS_LOAD_ERROR__ || typeof ts === 'undefined') {
      writeResult({ fatal: 'Could not load the TypeScript compiler from cdn.jsdelivr.net (offline?). The first run needs internet access; later runs use the Edge cache.' });
      return;
    }
    if (!input || window.__INPUT_LOAD_ERROR__) {
      writeResult({ fatal: 'The generated input (.out/typecheck-input.js) was not loaded. Run tools/typecheck.ps1 instead of opening the page directly.' });
      return;
    }
    input.typesFor = input.typesFor || {};
    var converted = ts.convertCompilerOptionsFromJson(input.compilerOptions, '/');
    if (converted.errors.length) {
      writeResult({ fatal: 'Invalid compiler options: ' + converted.errors.map(function (d) { return ts.flattenDiagnosticMessageText(d.messageText, ' '); }).join('; ') });
      return;
    }
    options = converted.options;
    options.noEmit = true;

    Object.keys(input.files).sort().forEach(function (rel) {
      var path = '/' + rel;
      addAppFile(path, input.files[rel]);
      if (/\.(ts|tsx)$/.test(rel)) appFiles.push(path);
    });
    var usesIcons = appFiles.some(function (f) {
      return ts.preProcessFile(vfs.get(f), true, true).importedFiles.some(function (r) { return r.fileName === '@expo/vector-icons'; });
    });
    if (usesIcons && !input.shimAll) addAppFile(GLYPH_FILE, GLYPH_SOURCE);

    setProgress('acquiring types');
    await acquireTypes();
    if (cacheStats.added > 0) {
      var cacheEl = document.createElement('pre');
      cacheEl.id = 'typecheck-cache';
      cacheEl.hidden = true;
      cacheEl.textContent = asciiJson({ version: 1, responses: cacheOut });
      document.body.appendChild(cacheEl);
    }

    checkAllowedImports();
    checkSnackSyntax();
    checkThemeReads();
    setProgress('type checking');
    var checked = check();

    var diagnostics = contractViolations.concat(checked.diagnostics);
    var packageList = Array.from(packages.values()).map(function (p) {
      return { name: p.name, version: p.version, range: p.range, state: p.state, error: p.error, fetched: p.fetched };
    }).sort(function (a, b) { return a.name < b.name ? -1 : a.name > b.name ? 1 : 0; });
    var shimList = [];
    shimmed.forEach(function (reason, name) { shimList.push({ name: name, reason: reason }); });

    setProgress('done');
    writeResult({
      ok: !diagnostics.some(function (d) { return d.category === 'error'; }),
      tsVersion: ts.version,
      userAgent: navigator.userAgent,
      appFiles: appFiles.length,
      programFiles: checked.sourceFiles,
      icons: checked.icons,
      diagnostics: diagnostics,
      packages: packageList,
      shimmed: shimList,
      unresolvedInLibraries: unresolvedInLibraries,
      stats: { requests: stats.requests, bytes: stats.bytes, failures: stats.failures, cacheHits: cacheStats.hits },
      options: input.compilerOptions
    });
  }

  main().catch(function (e) {
    writeResult({ fatal: 'Type checker crashed: ' + (e && e.stack ? e.stack : String(e)) });
  });
})();
